mapper.select:
select id as relationId, invitee_user_id as inviteeUserId, invite_code as inviteCode, relation_status as status, bound_at as boundAt, first_team_completed_at as firstTeamCompletedAt from invite_relation where inviter_user_id = #{userId} and deleted = 0
and relation_status = #{status}
order by bound_at desc limit #{offset}, #{size}

select count(*) from invite_relation
where inviter_user_id = #{userId} and deleted = 0

    and relation_status = #{status}

select uc.id, uc.template_id as templateId, ct.coupon_name as couponName, ct.coupon_type as couponType, ct.threshold_amount as thresholdAmount, ct.discount_amount as discountAmount, uc.coupon_status as couponStatus, uc.valid_start_at as validStartAt, uc.valid_end_at as validEndAt from user_coupon uc join coupon_template ct on ct.id = uc.template_id where uc.user_id = #{userId} and uc.deleted = 0 and ct.deleted = 0
and uc.coupon_status = #{status}
and ct.coupon_type = #{type}
order by uc.valid_end_at limit #{offset}, #{size}

select count(*)
from user_coupon uc
join coupon_template ct on ct.id = uc.template_id
where uc.user_id = #{userId} and uc.deleted = 0 and ct.deleted = 0

    and uc.coupon_status = #{status}


    and ct.coupon_type = #{type}

select id as draftId, user_id as userId, start_location_json as startJson, end_location_json as endJson, waypoint_json as waypointJson, departure_time as departureTime, duration_days as durationDays, people_count as peopleCount, remark, draft_status as draftStatus, published_trip_id as publishedTripId, updated_at as updatedAt from trip_draft where user_id = #{userId} and deleted = 0
and draft_status = #{status}
order by updated_at desc limit #{offset}, #{size}

select count(*) from trip_draft
where user_id = #{userId} and deleted = 0

    and draft_status = #{status}
